import { fileURLToPath } from "node:url";
import { readMigrationFiles } from "drizzle-orm/migrator";
import type { Database } from "./database.js";

/**
 * Folder of the SQL migrations generated by drizzle-kit (`pnpm db:generate`), at the root of
 * the package. Resolved from this module, which sits one level below the root both as source
 * (`src/`) and once built (`dist/`): the migrations ship next to `dist/`, never inside it.
 */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL("../migrations", import.meta.url));

/** Default table recording the migrations already applied, in Drizzle's format. */
export const MIGRATIONS_TABLE = "__drizzle_migrations";

export interface MigrateOptions {
  /** Folder written by drizzle-kit (`meta/_journal.json` + SQL files); default: the core's. */
  readonly migrationsFolder?: string;
  /**
   * Table recording the migrations applied from that folder, each set of migrations (a module's,
   * for instance) needing its own. Same format as Drizzle's migrator: `hash`, `created_at`.
   */
  readonly migrationsTable?: string;
}

/** Number of foreign key violations per table, by table name: `child: 2, navigation: 1`. */
function summarizeViolations(violations: readonly { table: string }[]): string {
  const counts = new Map<string, number>();
  for (const { table } of violations) {
    counts.set(table, (counts.get(table) ?? 0) + 1);
  }
  return [...counts]
    .sort(([first], [second]) => first.localeCompare(second))
    .map(([table, count]) => `${table}: ${count}`)
    .join(", ");
}

function quoteIdentifier(name: string): string {
  return `"${name.replaceAll('"', '""')}"`;
}

/**
 * Applies the pending migrations (by default, those of this package) and returns how many were
 * applied. A migration is pending when it is more recent (journal `when`) than the last one
 * recorded, as with Drizzle's migrator, whose tracking table this function shares.
 *
 * Everything happens in one `BEGIN IMMEDIATE` transaction, taken before reading what is already
 * applied, so that two processes cannot apply the same migrations. If a migration fails, or if
 * the applied migrations leave a foreign key violation, the transaction is rolled back and the
 * database stays exactly as it was. With nothing pending, it changes and checks nothing, so the
 * previous version of the application still starts on a database a later version migrated.
 *
 * Foreign keys are suspended meanwhile, as SQLite requires to rebuild a table: drizzle-kit
 * rebuilds tables to alter them, and its own `PRAGMA foreign_keys=OFF` has no effect inside a
 * transaction. Without this, rebuilding a parent table would cascade-delete its children.
 */
export function migrate(db: Database, options: MigrateOptions = {}): number {
  const { migrationsFolder = MIGRATIONS_FOLDER, migrationsTable = MIGRATIONS_TABLE } = options;
  const client = db.$client;
  if (client.inTransaction) {
    throw new Error("Migrations cannot run inside a transaction.");
  }
  const migrations = readMigrationFiles({ migrationsFolder });
  const table = quoteIdentifier(migrationsTable);

  const foreignKeys = client.pragma("foreign_keys", { simple: true }) === 1;
  client.pragma("foreign_keys = OFF");
  try {
    client.exec(
      `CREATE TABLE IF NOT EXISTS ${table} (id SERIAL PRIMARY KEY, hash text NOT NULL, created_at numeric)`,
    );
    client.exec("BEGIN IMMEDIATE");
    try {
      const lastApplied = client
        .prepare(`SELECT created_at FROM ${table} ORDER BY created_at DESC LIMIT 1`)
        .pluck()
        .get();
      const pending = migrations.filter(
        (migration) => lastApplied == null || Number(lastApplied) < migration.folderMillis,
      );
      const record = client.prepare(`INSERT INTO ${table} (hash, created_at) VALUES (?, ?)`);
      for (const migration of pending) {
        for (const statement of migration.sql) {
          client.exec(statement);
        }
        record.run(migration.hash, migration.folderMillis);
      }
      if (pending.length > 0) {
        const violations = client.pragma("foreign_key_check") as { table: string }[];
        if (violations.length > 0) {
          throw new Error(
            `Migrations rolled back: they would leave foreign key violations (${summarizeViolations(violations)}).`,
          );
        }
      }
      client.exec("COMMIT");
      return pending.length;
    } catch (error) {
      if (client.inTransaction) {
        client.exec("ROLLBACK");
      }
      throw error;
    }
  } finally {
    client.pragma(`foreign_keys = ${foreignKeys ? "ON" : "OFF"}`);
  }
}
